#include "bridge.h"
#include <string.h>
static uint32_t get(const uint8_t*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static void put(uint8_t*p,uint32_t x){for(unsigned i=0;i<4;i++)p[i]=(uint8_t)(x>>(8*i));}
mid_id fg_service(uint32_t id){mid_id dst={{2,255,(uint8_t)(id>>24),(uint8_t)(id>>16),(uint8_t)(id>>8),(uint8_t)id}};return dst;}
static int valid(const fg_packet*p){if(p->kind<1||p->kind>4||!p->pc_id||!p->transaction||p->len>140)return 0;if(p->kind==FG_DOWN)return p->session&&p->len<=128;if(p->kind==FG_UP)return p->len<=128;if(p->kind==FG_RECEIPT)return p->session&&p->len>=8&&p->len<=136;return p->len>=28&&p->len<=52;}
int fg_encode(const fg_packet*p,uint8_t*b,size_t cap){if(!valid(p)||cap<(size_t)FG_HEADER+p->len)return -1;memcpy(b,"FG02",4);b[4]=p->kind;b[5]=0;b[6]=(uint8_t)p->len;b[7]=(uint8_t)(p->len>>8);put(b+8,p->pc_id);put(b+12,p->session);put(b+16,p->transaction);memcpy(b+20,p->body,p->len);return 20+p->len;}
int fg_decode(fg_packet*p,const uint8_t*b,size_t len){if(len<20||len>160||memcmp(b,"FG02",4)||b[5])return -1;fg_packet t={.kind=b[4],.pc_id=get(b+8),.session=get(b+12),.transaction=get(b+16),.len=(uint16_t)(b[6]|((uint16_t)b[7]<<8))};if(t.len!=len-20||t.len>140)return -1;memcpy(t.body,b+20,t.len);if(!valid(&t))return -1;*p=t;return 0;}
int fg_request_check(fg_node*n,const fg_packet*p,mid_id dst,fg_request**out){for(unsigned i=0;i<16;i++){fg_request*r=&n->requests[i];if(r->used&&r->pc_id==p->pc_id&&r->session==p->session&&r->transaction==p->transaction){*out=r;return r->len==p->len&&mid_equal(r->dst,dst)&&!memcmp(r->bytes,p->body,p->len)?1:-1;}}*out=NULL;return 0;}
fg_request*fg_request_commit(fg_node*n,const fg_packet*p,mid_id dst,uint32_t seq){fg_request*r=&n->requests[n->request_next++%16];if(r->used)n->request_evictions++;*r=(fg_request){.used=1,.pc_id=p->pc_id,.session=p->session,.transaction=p->transaction,.source_seq=seq,.dst=dst,.len=p->len};memcpy(r->bytes,p->body,p->len);return r;}
int fg_destination(fg_node*n,const fg_packet*p){for(unsigned i=0;i<32;i++){fg_delivery*r=&n->deliveries[i];if(r->used&&r->pc_id==p->pc_id&&r->session==p->session&&r->transaction==p->transaction)return r->len==p->len&&!memcmp(r->bytes,p->body,p->len)?0:-1;}fg_delivery*r=&n->deliveries[n->delivery_next++%32];if(r->used)n->delivery_evictions++;*r=(fg_delivery){.used=1,.pc_id=p->pc_id,.session=p->session,.transaction=p->transaction,.len=p->len};memcpy(r->bytes,p->body,p->len);return 1;}
